class Node:
    def __init__(self, val, prev=None, next=None, child=None):
        self.val = val
        self.prev = prev
        self.next = next
        self.child = child


def build_multilevel(vals, children):
    if not vals:
        return None

    nodes = [Node(v) for v in vals]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]
        nodes[i + 1].prev = nodes[i]

    for i, child_encoding in enumerate(children):
        if child_encoding is not None:
            child_vals, child_children = child_encoding
            nodes[i].child = build_multilevel(child_vals, child_children)

    return nodes[0]


def flatten(head):
    curr = head
    stack = []
    while curr:
        if curr.child:
            if curr.next:
                stack.append(curr.next)
            curr.next = curr.child
            curr.next.prev = curr
            curr.child = None
        elif not curr.next and stack:
            nxt = stack.pop()
            curr.next = nxt
            nxt.prev = curr
        curr = curr.next
    return head


def flatten_multilevel_list(vals, children):
    head = build_multilevel(vals, children)
    flat_head = flatten(head)
    result = []
    node = flat_head
    while node:
        result.append(node.val)
        node = node.next
    return result

